const CWA_BASE='https://cwaopendata.s3.ap-northeast-1.amazonaws.com/';
const CWA_FILES=['Observation/O-A0001-001.json','Observation/O-A0003-001.json','Forecast/F-D0047-089.json','Forecast/F-D0047-091.json','Warning/W-C0033-002.json'];
function weatherNumber(value){if(value===null||value===undefined||String(value).trim()==='')return null;const n=Number(value);return Number.isFinite(n)&&n>-90?n:null}
function normalizeStations(raw,includeIncomplete=false){const c=raw?.cwaopendata,stations=c?.dataset?.Station;if(!Array.isArray(stations))throw Error('觀測資料格式不符');return stations.map(s=>{const geo=s.GeoInfo||{},point=geo.Coordinates?.find(p=>p.CoordinateName==='WGS84'),w=s.WeatherElement||{},temp=weatherNumber(w.AirTemperature);if(!point||(!includeIncomplete&&temp===null)||!Number.isFinite(Date.parse(s.ObsTime?.DateTime)))return null;const lat=Number(point.StationLatitude),lon=Number(point.StationLongitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))return null;const text=v=>typeof v==='string'&&!v.startsWith('-99')?v:null;return{id:s.StationId,name:s.StationName,county:geo.CountyName,town:geo.TownName,lat,lon,time:s.ObsTime.DateTime,temp,weather:text(w.Weather),humidity:weatherNumber(w.RelativeHumidity),pressure:weatherNumber(w.AirPressure),rain:weatherNumber(w.Now?.Precipitation),wind:weatherNumber(w.WindSpeed),direction:(weatherNumber(w.WindDirection)!==null&&Number(w.WindDirection)<=360&&Number(w.WindDirection)>=0?Number(w.WindDirection):null),gust:weatherNumber(w.GustInfo?.PeakGustSpeed),uv:weatherNumber(w.UVIndex),visibility:text(w.VisibilityDescription),high:weatherNumber(w.DailyExtreme?.DailyHigh?.TemperatureInfo?.AirTemperature),low:weatherNumber(w.DailyExtreme?.DailyLow?.TemperatureInfo?.AirTemperature)}}).filter(Boolean)}
function normalizeForecast(raw){const d=raw?.cwaopendata?.Dataset,locations=d?.Locations?.Location;if(!Array.isArray(locations))throw Error('預報資料格式不符');const cities={};for(const l of locations){const elements={};for(const e of l.WeatherElement||[])elements[e.ElementName]=(e.Time||[]).map(t=>({start:t.DataTime||t.StartTime,end:t.EndTime||null,value:t.ElementValue}));cities[l.LocationName]={elements}}return{issued:d.DatasetInfo?.IssueTime,updated:d.DatasetInfo?.Update,cities}}
function distanceKm(a,b){const r=x=>x*Math.PI/180,dl=r(b.lat-a.lat),dn=r(b.lon-a.lon),h=Math.sin(dl/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(dn/2)**2;return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
function nearestStation(stations,point,county){const valid=stations.filter(s=>!county||s.county===county);return valid.map(s=>({...s,distance:distanceKm(point,s)})).sort((a,b)=>a.distance-b.distance)[0]||null}
function forecastValue(city,name,key,at){const rows=city?.elements?.[name]||[],time=+new Date(at);let row=rows.find(t=>{const a=Date.parse(t.start);return t.end?a<=time&&time<Date.parse(t.end):a===time});if(!row&&!rows.some(t=>t.end)){row=rows.find(t=>Date.parse(t.start)>=time&&Date.parse(t.start)-time<=3600000)}return row?.value?.[key]??null}
function weatherKind(text=''){if(/雷/.test(text))return'thunder';if(/雨/.test(text))return'rain';if(/雪/.test(text))return'snow';if(/陰|霧/.test(text))return'cloud';if(/多雲/.test(text))return'partly';return'sun'}

function metricObservation(samples,primary,field,point,now=Date.now(),maxDistance=35){
 if(!point)return null;const valid=(samples||[]).filter(s=>{const age=now-Date.parse(s.time),v=s[field];return age>=-300000&&age<=5400000&&v!==null&&v!==undefined&&v!==''&&(field==='visibility'?/^(?:[<>≤≥]?\s*)?\d+(?:\.\d+)?$/.test(String(v).trim()):Number.isFinite(v)&&v>=0&&(field!=='pressure'||v>0)&&(field!=='humidity'||v<=100))}).map(s=>({...s,distance:distanceKm(point,s)})).filter(s=>s.distance<=maxDistance);
 valid.sort((a,b)=>(a.id===primary?.id?-1:0)-(b.id===primary?.id?-1:0)||a.distance-b.distance||Date.parse(b.time)-Date.parse(a.time));return valid[0]||null;
}
function normalizeWarnings(raw){
 const c=raw?.cwaopendata;if(!c||!c.dataset||typeof c.dataset!=='object')throw Error('警特報格式不符');if(c.msgType==='Cancel')return[];const array=v=>v==null?[]:Array.isArray(v)?v:[v],warnings=[];
 for(const[d,index]of array(c.dataset).map((d,i)=>[d,i])){const info=d.datasetInfo;if(!info)continue;const content=array(d.contents?.content).map(x=>x.contentText||'').filter(Boolean).join('\n\n'),start=info.validTime?.startTime,end=info.validTime?.endTime,issued=info.issueTime;if(!content)continue;if(!Number.isFinite(Date.parse(start))||!Number.isFinite(Date.parse(end))||!Number.isFinite(Date.parse(issued))||Date.parse(end)<=Date.parse(start))throw Error('警特報時間不符');const areas=[];for(const hs of array(d.hazardConditions?.hazards))for(const h of array(hs?.hazard))for(const i of array(h?.info))for(const area of array(i?.affectedAreas?.location))if(typeof area.locationName==='string')areas.push(area.locationName);warnings.push({id:String(c.identifier||'warning')+'-'+index,title:info.datasetDescription||'氣象警特報',issued,start,end,content,areas:[...new Set(areas)]})}return warnings;
}
function activeWarnings(warnings,now=Date.now()){return(warnings||[]).filter(w=>Date.parse(w.start)<=now&&Date.parse(w.end)>now).sort((a,b)=>Date.parse(b.issued)-Date.parse(a.issued))}
// Announced warnings remain visible before their effective period starts.
function publishedWarnings(warnings,now=Date.now()){return(warnings||[]).filter(w=>Number.isFinite(Date.parse(w.issued))&&Date.parse(w.issued)<=now&&Number.isFinite(Date.parse(w.start))&&Date.parse(w.end)>now&&Date.parse(w.end)>Date.parse(w.start)).sort((a,b)=>Date.parse(b.issued)-Date.parse(a.issued))}

async function loadCwaWeather(fetcher=fetch){const result=await Promise.allSettled(CWA_FILES.map(async p=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetcher(CWA_BASE+p,{signal:controller.signal,headers:{Accept:'application/json'},cache:p.startsWith('Warning/')?'no-store':'default',cf:{cacheTtl:p.startsWith('Warning/')?0:300,cacheEverything:!p.startsWith('Warning/')}});if(!r.ok)throw Error('上游服務 '+r.status);const text=await r.text();if(text.length>6000000)throw Error('資料過大');return JSON.parse(text)}finally{clearTimeout(timer)}}));
 const stations=new Map(),errors=[];let hourly=null,weekly=null,warnings=null;const observations=[];result.forEach((r,i)=>{try{if(r.status!=='fulfilled')throw Error();if(i<2){for(const s of normalizeStations(r.value,true)){observations.push(s);if(s.temp===null)continue;const prev=stations.get(s.id);if(!prev||Date.parse(s.time)>=Date.parse(prev.time))stations.set(s.id,s)}}else if(i===2)hourly=normalizeForecast(r.value);else if(i===3)weekly=normalizeForecast(r.value);else warnings=normalizeWarnings(r.value)}catch{errors.push(CWA_FILES[i].split('/').pop())}});if(!stations.size&&!hourly&&!weekly)throw Error('無法取得中央氣象署資料');return{source:'中央氣象署',retrievedAt:new Date().toISOString(),stations:[...stations.values()],observations,hourly,weekly,warnings,unavailable:errors}}
async function loadCwaWarnings(fetcher=fetch){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);try{const r=await fetcher(CWA_BASE+'Warning/W-C0033-002.json',{signal:controller.signal,cache:'no-store',cf:{cacheTtl:0,cacheEverything:false}});if(!r.ok)throw Error('警特報連線失敗');const text=await r.text();if(text.length>2000000)throw Error('警特報資料過大');return normalizeWarnings(JSON.parse(text))}finally{clearTimeout(timer)}}

let weatherMemo=null,weatherExpires=0,weatherFlight=null;
async function weatherResponse(request){if(!['GET','HEAD'].includes(request.method))return Response.json({error:'METHOD_NOT_ALLOWED'},{status:405,headers:{Allow:'GET, HEAD'}});try{if(!weatherMemo||Date.now()>weatherExpires){if(!weatherFlight)weatherFlight=loadCwaWeather().then(data=>{weatherMemo=data;weatherExpires=Date.now()+(data.unavailable.length?60000:300000);return data}).finally(()=>weatherFlight=null);await weatherFlight}return new Response(request.method==='HEAD'?null:JSON.stringify(weatherMemo),{headers:{'Content-Type':'application/json;charset=utf-8','Cache-Control':'public, max-age=60','X-Content-Type-Options':'nosniff'}})}catch{return Response.json({error:'CWA_UNAVAILABLE',message:'目前無法取得中央氣象署資料，請稍後重試。'},{status:502,headers:{'Cache-Control':'no-store'}})}}
let warningMemo=null,warningExpires=0,warningFlight=null;
async function warningResponse(request){if(!['GET','HEAD'].includes(request.method))return Response.json({error:'METHOD_NOT_ALLOWED'},{status:405,headers:{Allow:'GET, HEAD'}});try{if(!warningMemo||Date.now()>warningExpires){if(!warningFlight)warningFlight=loadCwaWarnings().then(warnings=>{warningMemo=warnings;warningExpires=Date.now()+60000;return warnings}).finally(()=>warningFlight=null);await warningFlight}return new Response(request.method==='HEAD'?null:JSON.stringify({warnings:warningMemo}),{headers:{'Content-Type':'application/json;charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}})}catch{return Response.json({error:'CWA_WARNING_UNAVAILABLE'},{status:502,headers:{'Cache-Control':'no-store'}})}}

